function starChatScope(){return chatScope('session',starSessions.selectedGroupId)}
function teamChatScope(){return chatScope('team',teamSession.teamId+'|'+teamSession.teamMemberId)}
function confirmChatMessage(id){if(id&&chatOutbox[id])delete chatOutbox[id]}
function pendingChatHtml(scope,sessionId){return Object.keys(chatOutbox).map(function(id){var m=chatOutbox[id];if(m.scope!==scope)return '';var status=m.status==='failed'?'发送失败：'+m.error:m.status==='unknown'?'发送结果待确认':'';return '<div class="message-row user"><div class="message-bubble">'+esc(m.text)+messageAttachmentsHtml(m.attachments)+(status?'<div class="message-delivery-status">'+esc(status)+(m.status==='unknown'?' <button class="btn btn-sm" onclick="retryChatMessage(\''+esc(id)+'\')">重试确认</button>':'')+'</div>':'')+'</div></div>'}).join('')}
function renderChatOutbox(){renderStarweaveEvents();renderTeamSessionMessages()}
function queueChatMessage(scope,text,attachments,path,body){var id=body.requestId||starRequestId();body.requestId=id;var instance=curInstance&&curInstance.instanceId;var entry={id:id,scope:scope,text:text,attachments:attachments,body:body,url:path+(instance?'?instance='+encodeURIComponent(instance):''),status:'sending',startedAt:Date.now()};chatOutbox[id]=entry;renderChatOutbox();return entry}
async function deliverChatMessage(entry){entry.status='sending';renderChatOutbox();var timer=setTimeout(function(){if(chatOutbox[entry.id]===entry&&entry.status==='sending'){entry.status='unknown';renderChatOutbox()}},15000);try{var response=await fetch(entry.url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(entry.body)}),result=await response.json(),command=result.data||{},data=entry.body.action?command.data||{}:command;if(!response.ok||result.accepted===false||command.accepted===false){entry.status=response.status>=500?'unknown':'failed';entry.error=command.message||result.message||'请求失败';return null}entry.status='accepted';entry.confirmedSessionId=data.sessionId||null;return data}catch(e){entry.status='unknown';entry.error=e.message;return null}finally{clearTimeout(timer);renderChatOutbox()}}
async function retryChatMessage(id){var entry=chatOutbox[id];if(!entry||entry.status==='sending')return;await deliverChatMessage(entry);if(entry.scope===starChatScope()){await loadStarweaveSessions(false);if(entry.scope===starChatScope())await loadStarweaveSnapshot();}if(entry.scope===teamChatScope())await loadTeamSessionSnapshot()}
function teamMessageIdentity(message){return message.messageId||(message.payload||{}).messageId||null}
function teamMessageRevision(message){return Number(message.revision||(message.payload||{}).revision)||0}
function mergeTeamMessage(message){var id=teamMessageIdentity(message);if(id)confirmChatMessage(id);var index=id?teamSession.messages.findIndex(function(old){return teamMessageIdentity(old)===id}):-1;if(index<0)teamSession.messages.push(message);else if(teamMessageRevision(message)>=teamMessageRevision(teamSession.messages[index]))teamSession.messages[index]=message}
function starRequestId(){try{return crypto.randomUUID()}catch(e){return Date.now()+'-'+Math.random().toString(16).slice(2)}}
function selectedStarSession(){return starSessions.items.filter(function(s){return s.groupId===starSessions.selectedGroupId})[0]||null}
function syncStarweaveViewport(){if(activePage!=='sessions')return;var layout=document.querySelector('.session-layout');if(!layout)return;var gap=window.innerWidth<=860?14:28;layout.style.setProperty('--session-viewport-height',Math.max(320,window.innerHeight-layout.getBoundingClientRect().top-gap)+'px')}
function setStarweaveOperation(message){var overlay=document.getElementById('starSessionOperation'),text=document.getElementById('starSessionOperationText'),main=overlay&&overlay.closest('.session-main');if(!overlay)return;if(text&&message)text.textContent=message;overlay.classList.toggle('show',!!message);if(main)main.classList.toggle('operation-active',!!message);overlay.setAttribute('aria-hidden',message?'false':'true')}
