container.innerHTML=items.map(function(s){var state=normalized(s.state||'closed');return '<button class="session-item'+(s.groupId===starSessions.selectedGroupId?' active':'')+'" onclick="selectStarweaveSession(\''+esc(s.groupId)+'\')"><div class="session-item-row"><span class="session-status '+state+'">'+esc(s.state||'CLOSED')+'</span><span class="session-item-name">'+esc(s.robotName||'未命名')+'</span></div><div class="session-item-meta"><span>当前会话</span><span>'+esc((s.sessionId||'').slice(0,12))+'</span></div></button>'}).join('');
