async function selectStarweaveSession(groupId){if(starSessions.transitioning){showSnackbar('会话正在切换，请稍候');return}closeStarweaveStream();starSessions.selectedGroupId=groupId;starSessions.events=[];starSessions.lastSeq=0;starSessions.uploads=[];starSessions.followOutput=true;var sidebar=document.querySelector('.session-sidebar');if(sidebar)sidebar.classList.remove('open');renderStarweaveSessions();renderStarweaveSessionDetail();renderStarweaveUploads();await loadStarweaveSnapshot()}
function toggleStarSessionSidebar(){var sidebar=document.querySelector('.session-sidebar');if(sidebar)sidebar.classList.toggle('open')}
function contextUsageHtml(value){var known=value!==null&&value!==undefined&&value!==''&&isFinite(Number(value))&&Number(value)>=0;if(!known)return '';var pct=Math.max(0,Math.min(100,Math.round(Number(value)))),level=pct<60?'low':(pct<85?'medium':'high');return '<span class="context-usage '+level+'" style="--context-usage:'+pct+'" title="上下文用量：'+pct+'%"><span class="context-usage-ring"><svg class="context-usage-svg" viewBox="0 0 36 36" aria-hidden="true"><circle class="context-usage-track" cx="18" cy="18" r="15.9"></circle><circle class="context-usage-progress" cx="18" cy="18" r="15.9" pathLength="100" transform="rotate(-90 18 18)"></circle><text class="context-usage-value" x="18" y="20.5">'+pct+'%</text></svg></span></span>'}
