function renderStarweaveEvents(){var box=document.getElementById('starSessionMessages');if(!box)return;var follow=starSessions.followOutput!==false,scrollTop=box.scrollTop;if(!starSessions.events.length&&!pendingChatHtml(starChatScope(),(selectedStarSession()||{}).sessionId)){box.innerHTML='<div class="session-empty"><div><span class="material-icons" style="font-size:38px;color:#c6c5df">chat_bubble_outline</span><p>开始一段新对话</p></div></div>';return}box.innerHTML=reduceStarweaveEvents(starSessions.events).map(function(item){var p=item.payload||{};if(item.kind==='USER_MESSAGE_ACCEPTED')return '<div class="message-row user"><div class="message-bubble">'+esc(p.content||'')+messageAttachmentsHtml(p.attachments)+'</div></div>';if(item.kind==='assistant')return '<div class="message-row assistant"><div class="message-bubble"><div class="markdown">'+renderMarkdown(item.text)+'</div></div></div>';if(item.kind==='tool'){var tool=p.update||{};return '<div class="message-row tool-row"><div class="event-card tool"><div class="event-card-head"><span class="material-icons">construction</span><span class="tool-call-title">'+esc(p.title||'工具调用')+'</span><span class="session-status '+normalized(p.status)+'">'+esc(p.status||'running')+'</span></div><details><summary>输入与输出</summary><div class="event-detail">'+esc(JSON.stringify(tool,null,2))+'</div></details></div></div>'}return eventCardHtml(item)}).join('')+pendingChatHtml(starChatScope(),(selectedStarSession()||{}).sessionId);if(follow)box.scrollTop=box.scrollHeight;else box.scrollTop=scrollTop}
function scheduleStarweaveEventsRender(){if(starEventRenderFrame)return;starEventRenderFrame=requestAnimationFrame(function(){starEventRenderFrame=0;renderStarweaveEvents()})}
