function handleStarFileDrop(event){event.preventDefault();event.currentTarget.classList.remove('dragging');uploadStarweaveFiles(event.dataTransfer&&event.dataTransfer.files)}
function requestStarweaveAttachments(){var session=selectedStarSession();if(!session){showSnackbar('请先选择会话，再添加附件');return}if(!isAgentOperable(session.state)){showSnackbar('当前无法添加附件：会话状态为 '+(session.state||'UNKNOWN'));return}var input=document.getElementById('starFileInput');if(input)input.click()}
async function uploadStarweaveFiles(fileList){var session=selectedStarSession(),input=document.getElementById('starFileInput'),files=Array.prototype.slice.call(fileList||[]);if(input)input.value='';if(!files.length){showSnackbar('未选择任何文件');return}if(!session){showSnackbar('请先选择会话，再添加附件');return}if(!isAgentOperable(session.state)){showSnackbar('当前无法添加附件：会话状态为 '+(session.state||'UNKNOWN'));return}if(starSessions.uploads.length+files.length>10){showSnackbar('每条消息最多添加 10 个附件');return}showSnackbar('已选择 '+files.length+' 个文件，正在上传');for(var i=0;i<files.length;i++){let file=files[i],item={fileName:file.name,size:file.size,uploadId:'',error:''};starSessions.uploads.push(item);renderStarweaveUploads();if(file.size<=0||file.size>20*1024*1024){item.error='文件需小于 20 MiB';renderStarweaveUploads();continue}try{var content=await fileAsBase64(file),result=await starPost('uploads',{groupId:session.groupId,sessionId:session.sessionId,generation:session.generation,fileName:file.name,contentBase64:content});if(session.groupId!==(selectedStarSession()&&selectedStarSession().groupId)||Number(session.generation)!==Number((selectedStarSession()||{}).generation)){item.error='会话已切换，请重新选择文件'}else item.uploadId=result.uploadId}catch(e){item.error=e.message||'上传失败'}renderStarweaveUploads()}var succeeded=starSessions.uploads.filter(function(u){return !!u.uploadId}).length,failed=starSessions.uploads.filter(function(u){return !!u.error}).length;showSnackbar(failed?'附件上传完成：'+succeeded+' 个就绪，'+failed+' 个失败':'附件已就绪，将随下一条消息发送')}
async function sendStarweaveMessage(){var session=selectedStarSession(),input=document.getElementById('starMessageInput'),message=input.value.trim(),pending=starSessions.uploads.filter(function(u){return !u.uploadId&&!u.error}),ready=starSessions.uploads.filter(function(u){return !!u.uploadId});if(!session||(!message&&!ready.length))return;if(pending.length){showSnackbar('附件仍在上传，请稍候');return}if(!message)message='请查看附件。';starSessions.followOutput=true;var scope=starChatScope(),entry=queueChatMessage(scope,message,ready,'/api/starweave/v1/sessions/messages',{groupId:session.groupId,message:message,expectedSessionId:session.sessionId,expectedGeneration:session.generation,uploadIds:ready.map(function(u){return u.uploadId})});input.value='';starSessions.uploads=[];renderStarweaveUploads();await deliverChatMessage(entry);if(scope!==starChatScope())return;await loadStarweaveSessions(false);if(scope===starChatScope())connectStarweaveStream()}
function chatEnterSends(event){return event.key==='Enter'&&!event.shiftKey&&!event.isComposing&&event.keyCode!==229&&!window.matchMedia('(max-width:860px), (pointer:coarse)').matches}
function starMessageKeydown(event){if(chatEnterSends(event)){event.preventDefault();sendStarweaveMessage()}}
function resizeChatInput(input,height){
var compose=input.closest('.session-compose'),main=input.closest('.session-main'),head=main.querySelector('.session-head'),minimum=parseFloat(window.getComputedStyle(input).minHeight)||64;
var overhead=compose.getBoundingClientRect().height-input.getBoundingClientRect().height;
var maximum=Math.max(minimum,main.getBoundingClientRect().height-head.getBoundingClientRect().height-overhead-100);
input.style.height=Math.max(minimum,Math.min(maximum,height))+'px';
}
function startChatInputResize(event){
if(event.button!==0)return;
var handle=event.currentTarget,input=handle.parentElement.querySelector('textarea'),startY=event.clientY,startHeight=input.getBoundingClientRect().height,pointerId=event.pointerId;
event.preventDefault();handle.setPointerCapture(pointerId);
function move(e){if(e.pointerId===pointerId)resizeChatInput(input,startHeight+startY-e.clientY)}
function finish(e){if(e.pointerId!==pointerId)return;handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',finish);handle.removeEventListener('pointercancel',finish);handle.removeEventListener('lostpointercapture',finish);if(handle.hasPointerCapture(pointerId))handle.releasePointerCapture(pointerId)}
handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',finish);handle.addEventListener('pointercancel',finish);handle.addEventListener('lostpointercapture',finish);
}
function chatInputResizeKeydown(event){if(event.key!=='ArrowUp'&&event.key!=='ArrowDown')return;event.preventDefault();var input=event.currentTarget.parentElement.querySelector('textarea');resizeChatInput(input,input.getBoundingClientRect().height+(event.key==='ArrowUp'?24:-24))}
async function cancelStarweaveSession(){var s=selectedStarSession();if(!s){showSnackbar('请先选择会话');return}if(starSessionOperationPending())return;if(s.state!=='BUSY'){showSnackbar('当前无法取消会话：没有正在执行的任务');return}try{await starPost('cancel',{groupId:s.groupId,expectedSessionId:s.sessionId,expectedGeneration:s.generation});showSnackbar('已请求取消');await loadStarweaveSessions(false)}catch(e){showSnackbar('取消失败: '+e.message)}}
async function startStarweaveSession(){var s=selectedStarSession();if(!s){showSnackbar('请先选择会话');return}if(starSessionOperationPending())return;if(s.state!=='CLOSED'){showSnackbar('当前无需启动会话：会话状态为 '+(s.state||'UNKNOWN'));return}var transition=beginStarweaveTransition('正在启动「'+s.robotName+'」的会话…');try{var started=await starPost('open',{robotName:s.robotName});starSessions.selectedGroupId=started.groupId;starSessions.events=[];starSessions.lastSeq=0;starSessions.followOutput=true;endStarweaveTransition(transition);await loadStarweaveSessions(false);await refreshChannelBindingTargets(false);await loadStarweaveSnapshot();showSnackbar('会话已启动')}catch(e){showSnackbar('启动会话失败: '+e.message)}finally{endStarweaveTransition(transition);setStarweaveOperation('')}}
async function newStarweaveSession(){var s=selectedStarSession();if(!s){showSnackbar('请先选择会话');return}if(starSessionOperationPending())return;if(!isAgentOperable(s.state)){showSnackbar('当前无法新建会话：会话状态为 '+(s.state||'UNKNOWN'));return}if(!await showConfirm('将为「'+s.robotName+'」创建新会话，当前会话会保留在历史列表中。',{title:'新建会话？',confirmText:'新建会话'}))return;var transition=beginStarweaveTransition('正在新建会话…');try{var next=await starPost('new',{groupId:s.groupId,expectedSessionId:s.sessionId,expectedGeneration:s.generation});starSessions.selectedGroupId=next.groupId;starSessions.events=[];starSessions.lastSeq=0;starSessions.followOutput=true;endStarweaveTransition(transition);await loadStarweaveSessions(false);await refreshChannelBindingTargets(false);await loadStarweaveSnapshot();showSnackbar('新会话已创建')}catch(e){showSnackbar('新建会话失败: '+e.message)}finally{endStarweaveTransition(transition);setStarweaveOperation('')}}
function openStarweaveRestoreDialog(){var s=selectedStarSession(),list=document.getElementById('starRestoreList'),confirmButton=document.getElementById('starRestoreConfirm');if(!s){showSnackbar('请先选择会话');return}if(starSessionOperationPending())return;var history=(s.sessions||[]).filter(function(item){return !item.current});if(!history.length){showSnackbar('当前无历史会话');return}if(!isAgentOperable(s.state)){showSnackbar('当前无法恢复会话：会话状态为 '+(s.state||'UNKNOWN'));return}if(!list)return;list.innerHTML=history.map(function(item,index){var id='star-history-'+index;return '<label class="session-history-option" for="'+id+'"><input type="radio" name="starRestoreTarget" id="'+id+'" value="'+esc(item.sessionId)+'" onchange="document.getElementById(\'starRestoreConfirm\').disabled=false"><strong>'+esc(item.preview||'历史会话')+'</strong><small>'+esc(item.sessionId||'')+'</small></label>'}).join('');if(confirmButton)confirmButton.disabled=true;showDialog('starRestoreDialog')}
async function restoreStarweaveSession(){var s=selectedStarSession(),selected=document.querySelector('input[name="starRestoreTarget"]:checked'),target=selected&&selected.value;if(!s||!target)return;closeDialog('starRestoreDialog');var transition=beginStarweaveTransition('正在恢复历史会话…');try{var restored=await starPost('restore',{groupId:s.groupId,targetSessionId:target,expectedSessionId:s.sessionId,expectedGeneration:s.generation});starSessions.selectedGroupId=restored.groupId;starSessions.events=[];starSessions.lastSeq=0;starSessions.followOutput=true;endStarweaveTransition(transition);await loadStarweaveSessions(false);await refreshChannelBindingTargets(false);await loadStarweaveSnapshot();showSnackbar('历史会话已恢复')}catch(e){showSnackbar('恢复失败: '+e.message)}finally{endStarweaveTransition(transition);setStarweaveOperation('')}}
async function deleteStarweaveSession(){var s=selectedStarSession();if(!s){showSnackbar('请先选择会话');return}if(starSessionOperationPending())return;if(s.state==='BUSY'){showSnackbar('当前无法删除会话：请先取消正在执行的任务');return}if(!await showConfirm('删除「'+s.robotName+'」的当前 Starweave 会话后，再次开启会创建全新 session。',{title:'删除当前会话？',confirmText:'删除会话',danger:true}))return;try{closeStarweaveStream();await starPost('delete',{groupId:s.groupId,expectedSessionId:s.sessionId,expectedGeneration:s.generation});starSessions.events=[];starSessions.lastSeq=0;await loadStarweaveSessions(false);await refreshChannelBindingTargets(false);showSnackbar('会话已删除')}catch(e){showSnackbar('删除失败: '+e.message)}}
async function loadStarweaveTeams(notify){var box=document.getElementById('starTeamList');if(!box)return;try{var response=await api('/api/starweave/v1/teams'),result=await response.json();if(!response.ok||result.accepted===false)throw new Error(result.message||'团队加载失败');starTeams.items=(((result.data||{}).data||{}).teams)||[];document.getElementById('teamCount').textContent=starTeams.items.length;renderStarweaveTeams();if(notify)showSnackbar('团队已刷新')}catch(e){starTeams.items=[];document.getElementById('teamCount').textContent='0';box.innerHTML='<div class="resource-empty"><span class="material-icons">error_outline</span><strong>'+esc(e.message)+'</strong></div>';if(notify)showSnackbar('团队刷新失败: '+e.message)}}
function renderStarweaveTeams(){
var box=document.getElementById('starTeamList');if(!box)return;
if(!starTeams.items.length){box.innerHTML='<div class="filter-empty"><span class="material-icons">groups</span><p>暂无 Starweave 团队</p><small>创建团队后，可以让多个智能体在独立会话中协同工作</small></div>';return}
var delayed=starTeams.items.some(function(team){return !!team.coordinatorDelayed}),notice=delayed?'<div class="resource-empty"><span class="material-icons">schedule</span><strong>协调器延迟，当前状态可能已过期</strong></div>':'';
box.innerHTML=notice+starTeams.items.map(function(team){
var captain=team.captainTeamMemberId,all=team.members||[],mode=(team.mode||'NORMAL').toUpperCase(),operation=teamBatchOperations[team.teamId]||'',disabled=operation?' disabled':'',editReason=operation?'团队操作正在进行中':all.some(function(member){return !isAgentOperable(member.state)})?'请等待所有团队成员进入 READY':team.coordinated?'跨设备团队暂不支持修改成员':'',members=all.slice(0,3).map(function(member){var placement=member.sourceLabel?'<small class="team-source-label">'+esc(member.sourceLabel)+'</small>':'',captainBadge=member.teamMemberId===captain?'<span class="team-member-role">队长</span>':'',name=member.displayName||member.sourceRobotName||member.teamMemberId;return '<button type="button" class="team-member-preview-item" data-team-id="'+esc(team.teamId)+'" data-member-id="'+esc(member.teamMemberId)+'" onclick="openTeamSessionPreview(this)" title="进入 '+esc(name)+' 的会话"><span class="material-icons">smart_toy</span><strong>'+esc(name)+'</strong>'+captainBadge+placement+'<span class="session-status '+normalized(member.state)+'">'+esc(member.state||'STARTING')+'</span></button>'}).join(''),more=all.length>3?'<div class="team-member-more">还有 '+(all.length-3)+' 个成员，可在团队会话中查看</div>':'';
var editButton='<button class="btn btn-secondary btn-sm'+(editReason?' team-edit-unavailable':'')+'" data-team-id="'+esc(team.teamId)+'" onclick="openStarweaveTeamEditDialog(this.dataset.teamId)" title="'+esc(editReason||'修改队伍')+'" aria-label="修改队伍"'+(editReason?' disabled aria-disabled="true"':'')+'><span class="material-icons">edit</span></button>';
var actions='<div class="team-card-actions"><button class="btn btn-secondary btn-sm team-session-entry" onclick="openTeamSessionDialog(\''+esc(team.teamId)+'\')" title="团队会话" aria-label="团队会话"><span class="material-icons">forum</span></button>'+editButton+'<button class="btn btn-secondary btn-sm" onclick="runTeamBatchAction(\''+esc(team.teamId)+'\',\'newSession\')" title="为所有成员新建会话" aria-label="为所有成员新建会话"'+disabled+'><span class="material-icons">'+(operation==='newSession'?'hourglass_top':'add_comment')+'</span></button><button class="btn btn-secondary btn-sm" onclick="runTeamBatchAction(\''+esc(team.teamId)+'\',\'cancel\')" title="取消所有成员会话" aria-label="取消所有成员会话"'+disabled+'><span class="material-icons">'+(operation==='cancel'?'hourglass_top':'stop_circle')+'</span></button></div>';
var rebuilding=operation==='update'?'<div class="star-team-edit-note" role="status">正在重建团队并为成员创建新会话…</div>':'';
return '<div class="structured-item"><div class="team-card-head"><div class="team-card-identity"><span class="material-icons" style="color:var(--sw-primary)">hub</span><strong>'+esc(team.name||team.teamId)+'</strong><span class="team-member-role">'+(mode==='CAPTAIN'?'队长模式':'普通模式')+'</span><span class="session-status '+normalized(team.state)+'">'+esc(team.state)+'</span></div>'+actions+'</div>'+rebuilding+'<div class="team-member-preview">'+members+more+'</div><div style="margin-top:12px;text-align:right"><button class="btn btn-danger btn-sm" onclick="deleteStarweaveTeam(\''+esc(team.teamId)+'\','+Number(team.version||0)+','+(team.coordinated?'true':'false')+')"'+disabled+'><span class="material-icons">delete</span>删除</button></div></div>'
}).join('')
}
async function postTeamMemberAction(team,member,action){
var body={requestId:starRequestId(),action:action,teamId:team.teamId,teamMemberId:member.teamMemberId,acpClientId:member.acpClientId,sessionId:member.sessionId,coordinated:!!team.coordinated};
var response=await api('/api/starweave/v1/teams/member',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),result=await response.json(),command=result.data||{};
if(!response.ok||result.accepted===false||command.accepted===false)throw new Error(command.message||result.message||'操作失败');return command.data||{}
}
async function runTeamBatchAction(teamId,action){
var team=starTeams.items.filter(function(item){return item.teamId===teamId})[0],members=team&&team.members||[];if(!team){showSnackbar('团队不存在或已被删除');return}if(teamBatchOperations[teamId]){showSnackbar('当前团队操作尚未完成');return}if(!members.length){showSnackbar('团队中没有可操作的成员');return}
if(action==='newSession'){var unavailable=members.filter(function(member){return !isAgentOperable(member.state)});if(unavailable.length){showSnackbar('无法新建会话：请等待所有团队成员进入 READY');return}}
if(action==='newSession'&&!await showConfirm('将同时为团队「'+(team.name||team.teamId)+'」的 '+members.length+' 个成员创建新会话。各成员当前会话会保留在历史列表中。',{title:'为全部成员新建会话？',confirmText:'一键新建'}))return;
if(action==='cancel'&&!await showConfirm('将向团队「'+(team.name||team.teamId)+'」的全部 '+members.length+' 个成员发送取消请求，正在执行的工作会被中断。',{title:'取消全部成员会话？',confirmText:'全部取消',danger:true}))return;
teamBatchOperations[teamId]=action;renderStarweaveTeams();
try{var results=await Promise.all(members.map(function(member){return postTeamMemberAction(team,member,action).then(function(){return{ok:true,member:member}}).catch(function(error){return{ok:false,member:member,error:error}})})),failed=results.filter(function(result){return !result.ok});await loadStarweaveTeams(false);await refreshChannelBindingTargets(false);if(failed.length){var names=failed.map(function(result){return result.member.displayName||result.member.sourceRobotName||result.member.teamMemberId}).join('、');showSnackbar((action==='newSession'?'新建会话':'取消会话')+'完成：'+(members.length-failed.length)+' 个成功，'+failed.length+' 个失败（'+names+'）')}else showSnackbar(action==='newSession'?'所有团队成员的新会话已创建':'所有团队成员已完成取消请求')
}finally{delete teamBatchOperations[teamId];renderStarweaveTeams()}
}
function starTeamSourceKey(source){return [source.cmdProxyInstanceId||'',source.sourceGroupId||'',source.sourceRobotId||''].join('|')}
