function renderStarTeamSelectedMembers(){var box=document.getElementById('starTeamSelectedMembers');if(!box)return;var selected=Array.prototype.slice.call(document.querySelectorAll('#starTeamMembers .star-team-member:checked')).map(function(input){return starTeamDraft.sources.filter(function(source){return starTeamSourceKey(source)===input.value})[0]}).filter(Boolean);updateStarTeamCount('starTeam',selected.length);if(!selected.length){box.innerHTML='<div class="star-team-selected-empty">选择成员后，可在这里填写每位成员的团队职责</div>';updateStarTeamCreateState();return}box.innerHTML=selected.map(function(source){var key=starTeamSourceKey(source),value=starTeamDraft.remarks[key]||'',captain=starTeamDraft.mode==='CAPTAIN'?'<label class="star-team-captain-choice"><input class="star-team-captain-radio" type="radio" name="starTeamCaptain" value="'+esc(key)+'" '+(starTeamDraft.captainKey===key?'checked':'')+' onchange="starTeamDraft.captainKey=this.value;updateStarTeamCreateState()"><span>设为队长</span></label>':'';return '<div class="star-team-selected-member"><div class="star-team-selected-identity"><span class="star-team-selected-name" title="'+esc(source.displayName||source.robotName)+'">'+esc(source.displayName||source.robotName)+'</span></div>'+captain+'<input class="star-team-member-remark" data-source-key="'+esc(key)+'" maxlength="200" value="'+esc(value)+'" placeholder="例如：负责需求分析" oninput="updateStarTeamMemberRemark(this)"></div>'}).join('');updateStarTeamCreateState()}
function updateStarTeamMemberRemark(input){starTeamDraft.remarks[input.getAttribute('data-source-key')]=input.value}
function setStarTeamMode(mode){starTeamDraft.mode=mode==='CAPTAIN'?'CAPTAIN':'NORMAL';if(starTeamDraft.mode==='NORMAL')starTeamDraft.captainKey='';document.getElementById('starTeamModeHelp').textContent=starTeamDraft.mode==='CAPTAIN'?'队长可联系所有队员，普通队员只能联系队长；外部信道和任务仅由队长承接。':'成员之间可以相互查看并直接通信。';renderStarTeamSelectedMembers()}
