function removeFileLinkError(){var error=document.getElementById('fileLinkPreviewError');if(error)error.remove()}
async function openFileLinkPreview(parsed,useTeam){
if(!parsed||parsed.remote)return;var context=fileLinkContext(!!useTeam);if(!context){showSnackbar(useTeam?'请先选择有效的团队成员会话':'请先选择有效会话');return}var token=++fileLinkPreview.request;fileLinkPreview.context=context;fileLinkPreview.data=null;showFileLinkLoading(parsed.target);var body=Object.assign({requestId:starRequestId(),target:parsed.target,requestedLine:parsed.requestedLine},context.body);
try{var response=await api(context.path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),result=await response.json();if(token!==fileLinkPreview.request)return;if(context.key!==currentFileLinkContextKey(context.type)){closeFileLinkPreview();return}if(!response.ok||result.accepted===false)throw new Error(fileLinkErrorMessage(result.code,result.message));var data=result.data||{};data.renderMode=fileLinkRenderMode(data);fileLinkPreview.data=data;fileLinkPreview.mode=(data.renderMode==='MARKDOWN'||data.renderMode==='HTML')?'PREVIEW':'SOURCE';renderFileLinkPreview()}catch(e){if(token!==fileLinkPreview.request)return;renderFileLinkError(e.message||'文件无法展示')}
}
function fileLinkErrorMessage(code,message){var labels={FILE_NOT_FOUND:'文件不存在',FILE_TOO_LARGE:'文件超过 1 MiB 预览限制',BINARY_FILE:'二进制文件不支持在线预览',NOT_REGULAR_FILE:'该路径不是普通文件',PERMISSION_DENIED:'没有权限读取该文件',PATH_NOT_ALLOWED:'该路径不允许访问',INVALID_ENCODING:'暂不支持该文件编码',BUSY:'文件预览请求过多，请稍后重试',REMOTE_FILE_PREVIEW_UNSUPPORTED:'跨实例团队成员暂不支持文件预览',SESSION_STALE:'会话已经切换，请重新点击链接'};return labels[code]||message||code||'文件无法展示'}
function renderFileLinkPreview(){
var data=fileLinkPreview.data;if(!data)return;document.getElementById('fileLinkPreviewLoading').classList.remove('show');removeFileLinkError();document.getElementById('fileLinkPreviewTitle').textContent=data.fileName||'文件预览';document.getElementById('fileLinkDownloadButton').style.display='inline-flex';var meta=[];if(data.charset)meta.push(data.charset);if(data.lineCount!=null)meta.push(data.lineCount+' 行');if(data.bytesRead!=null)meta.push(formatResourceBytes(data.bytesRead));if(data.requestedLine)meta.push('定位 L'+data.requestedLine);document.getElementById('fileLinkPreviewMeta').textContent=meta.join(' · ');hideFileLinkSurfaces();var toggle=document.getElementById('fileLinkModeButton'),previewable=data.renderMode==='MARKDOWN'||data.renderMode==='HTML';toggle.style.display=previewable?'inline-flex':'none';toggle.textContent=fileLinkPreview.mode==='PREVIEW'?'源码':'预览';if(fileLinkPreview.mode==='SOURCE'){renderFileLinkSource(data);return}if(data.renderMode==='MARKDOWN'){var markdown=document.getElementById('fileLinkPreviewMarkdown');markdown.innerHTML='<article class="markdown-body">'+renderMarkdown(data.content||'')+'</article>';markdown.hidden=false;return}renderFileLinkHtml(data)
}
function renderFileLinkSource(data){
var content=String(data.content||''),source=document.getElementById('fileLinkPreviewSource'),lines=Math.max(1,Number(data.lineCount)||content.split('\n').length),numbers=[];for(var i=1;i<=lines;i++)numbers.push(i);document.getElementById('fileLinkPreviewGutter').textContent=numbers.join('\n');document.getElementById('fileLinkPreviewCode').innerHTML=highlightResourceCode(content,fileLinkLanguage(data.fileName));source.hidden=false;source.scrollTop=0;source.scrollLeft=0;var focus=document.getElementById('fileLinkPreviewFocus');focus.style.display='none';if(data.requestedLine&&data.requestedLine<=lines){var lineHeight=window.innerWidth<=520?20:21,top=14+(data.requestedLine-1)*lineHeight;focus.style.top=top+'px';focus.style.display='block';requestAnimationFrame(function(){source.scrollTop=Math.max(0,top-source.clientHeight*.35)})}else if(data.requestedLine&&data.requestedLine>lines)showSnackbar('目标行超出文件范围')
}
function renderFileLinkHtml(data){var frame=document.getElementById('fileLinkPreviewFrame'),content=String(data.content||''),dark=document.documentElement.getAttribute('data-theme')==='dark',guard='<meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src \'unsafe-inline\'; img-src data:; font-src data:; script-src \'none\'; connect-src \'none\'; object-src \'none\'; frame-src \'none\'; form-action \'none\';"><style>html{color-scheme:'+(dark?'dark':'light')+'}body{margin:0;padding:24px 28px;background:'+(dark?'#151f32':'#fff')+';color:'+(dark?'#b8c3d4':'#263746')+';font:15px/1.7 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}img{max-width:100%}pre{overflow:auto}</style>';var html=/<head(?:\s[^>]*)?>/i.test(content)?content.replace(/<head(\s[^>]*)?>/i,function(head){return head+guard}):'<!doctype html><html><head>'+guard+'</head><body>'+content+'</body></html>';frame.srcdoc=html;frame.hidden=false}
function toggleFileLinkPreviewMode(){if(!fileLinkPreview.data)return;fileLinkPreview.mode=fileLinkPreview.mode==='PREVIEW'?'SOURCE':'PREVIEW';renderFileLinkPreview()}
function downloadFileLinkPreview(){var data=fileLinkPreview.data;if(!data)return;var blob=new Blob([String(data.content||'')],{type:(data.mediaType||'text/plain')+';charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=data.fileName||'download.txt';document.body.appendChild(link);link.click();link.remove();setTimeout(function(){URL.revokeObjectURL(url)},60000)}
function renderFileLinkError(message){document.getElementById('fileLinkPreviewLoading').classList.remove('show');hideFileLinkSurfaces();removeFileLinkError();document.getElementById('fileLinkModeButton').style.display='none';document.getElementById('fileLinkDownloadButton').style.display='none';document.getElementById('fileLinkPreviewMeta').textContent='';document.getElementById('fileLinkPreviewBody').insertAdjacentHTML('beforeend','<div class="file-link-error" id="fileLinkPreviewError"><span class="material-icons">error_outline</span><strong>文件无法展示</strong><small>'+esc(message)+'</small></div>')}
function closeFileLinkPreview(){fileLinkPreview.request+=1;fileLinkPreview.data=null;fileLinkPreview.context=null;removeFileLinkError();hideFileLinkSurfaces();document.getElementById('fileLinkDownloadButton').style.display='none';document.getElementById('fileLinkPreviewLoading').classList.remove('show');closeDialog('fileLinkPreviewDialog')}
document.addEventListener('click',function(event){var target=event.target&&event.target.closest?event.target.closest('a.star-file-link'):null;if(!target)return;var teamRoot=target.closest('#teamSessionMessages'),sessionRoot=target.closest('#starSessionMessages'),viewerRoot=target.closest('#fileLinkPreviewDialog');if(!teamRoot&&!sessionRoot&&!viewerRoot)return;var parsed=parseStarFilePreviewTarget(target.getAttribute('data-file-target')||target.getAttribute('href'));if(!parsed||parsed.remote)return;event.preventDefault();event.stopPropagation();var useTeam=!!teamRoot||!!(viewerRoot&&fileLinkPreview.context&&fileLinkPreview.context.type==='team');openFileLinkPreview(parsed,useTeam)});
document.addEventListener('keydown',function(event){if(event.key==='Escape'&&document.getElementById('fileLinkPreviewDialog').classList.contains('show'))closeFileLinkPreview()});
